-- Hand-written below this line (not generated by drizzle-kit).
-- RoboNest.3D does not operate resin printers: remove the "RESIN" choice from
-- a stored custom-print materials setting, if one exists. Other entries,
-- colours and existing customer requests are left untouched.
UPDATE `site_settings`
SET `value` = json_set(`value`, '$.materials', (
  SELECT json_group_array(json(m.value)) FROM json_each(`site_settings`.`value`, '$.materials') m
  WHERE upper(json_extract(m.value, '$.code')) <> 'RESIN'
))
WHERE `key` = 'customPrint' AND EXISTS (
  SELECT 1 FROM json_each(`site_settings`.`value`, '$.materials') m WHERE upper(json_extract(m.value, '$.code')) = 'RESIN'
);
